function foldQuery(s) {
  return String(s).toLowerCase().replace(/[üǖǘǚǜ]/g, 'v').replace(/[^a-z0-9\u4e00-\u9fff]+/g, '');
}

function hanSpell(s) {
  let full = '';
  let abbr = '';
  for (const ch of String(s)) {
    const py = HAN_PY[ch];
    if (py) {
      full += py;
      abbr += py[0];
    } else if (/[a-z0-9]/i.test(ch)) {
      const c = ch.toLowerCase();
      full += c;
      abbr += c;
    }
  }
  return { full, abbr };
}

function fontNeedles(font) {
  if (font._needles) return font._needles;
  const blob = [font.name, font.en, font.family, font.fullName, font.type, labels[font.type] || '', font.license, font.postscript].join(' ');
  const spell = hanSpell(`${font.name} ${font.type} ${labels[font.type] || ''}`);
  const poster = String(font.poster || '').replace(/-poster\.jpe?g$/i, '');
  const packed = foldQuery(`${blob} ${spell.full} ${spell.abbr} ${poster} ${spell.full.replace(/v/g, 'u')}`);
  font._needles = packed;
  return packed;
}

function fontHits(font, q) {
  if (!q) return true;
  const needle = fontNeedles(font);
  const folded = foldQuery(q);
  if (folded && needle.includes(folded)) return true;
  const tokens = String(q).toLowerCase().split(/[\s·,，]+/).map(foldQuery).filter(Boolean);
  return tokens.length > 1 && tokens.every((token) => needle.includes(token));
}

