const SAVE_KEY = 'ziku-saved';
const saved = new Set((() => {
  try { return JSON.parse(localStorage.getItem(SAVE_KEY) || '[]'); }
  catch { return []; }
})());

function fontKey(font) {
  return font.path || font.name;
}

function persistSaved() {
  localStorage.setItem(SAVE_KEY, JSON.stringify([...saved]));
}

function isSaved(font) {
  return saved.has(fontKey(font));
}

function toggleSaved(font) {
  const key = fontKey(font);
  if (saved.has(key)) saved.delete(key);
  else saved.add(key);
  persistSaved();
  return saved.has(key);
}

const heatBoosts = [
  [/霞鹜|LXGW|文楷|臻楷/i, 48000],
  [/思源|Source Han|Noto Serif|Noto Sans/i, 42000],
  [/阿里巴巴|阿里妈妈|Alibaba|Alimama/i, 36000],
  [/得意黑|Smiley Sans/i, 30000],
  [/朱雀|Zhuque/i, 24000],
  [/站酷|ZCOOL|仓耳/i, 18000],
  [/寒蝉|秋水|月星楷/i, 14000],
];

function heatScore(x, i) {
  if (Number(x.usage) > 0) return Number(x.usage);
  const name = `${x.name || ''} ${x.familyName || ''}`;
  let score = Math.max(180, Math.round((x.numGlyphs || 120) / 2.4));
  heatBoosts.forEach(([re, n]) => {
    if (re.test(name)) score += n;
  });
  score += ((i * 47) % 830);
  return score;
}

const formatUsage = (n) => (n >= 1e6 ? `${(n / 1e6).toFixed(1)}m` : n >= 1000 ? `${(n / 1e3).toFixed(1)}k` : String(n));

const normalize = (x, i) => ({
  name: x.name || x.familyName || `未命名字体 ${i + 1}`,
  en: x.familyName || x.fullName || 'Open Font',
  fullName: x.fullName || '',
  family: x.familyName || '',
  subfamily: x.subfamilyName || '',
  postscript: x.postscriptName || '',
  version: x.version || '',
  copyright: (x.copyright || '').replace(/\s+/g, ' ').trim(),
  home: x.home || '',
  type: x.type || '艺术体',
  license: x.license || '',
  size: x.size || '—',
  glyphs: x.numGlyphs || 0,
  usage: heatScore(x, i),
  byte: Number(x.byte) || 0,
  path: x.path || '',
  poster: x.poster || '',
});

const escapeHtml = (s) => String(s).replace(/[&<>"']/g, (c) => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
}[c]));

function currentPoet() {
  return poets.find((item) => item.id === poetId) || poets[0];
}

function currentWork() {
  const poet = currentPoet();
  return poet.works.find((item) => item.id === workId) || poet.works[0];
}

function currentSample() {
  if (lang === 'custom') return customText.value.trim() || '输入你的文字';
  if (lang === 'zh') return currentWork()[length];
  return samples[lang][length];
}

function currentCite() {
  if (lang !== 'zh') return '';
  return `${currentPoet().name} · ${currentWork().title}`;
}

function applyPreviewText() {
  const text = currentSample();
  previewDisplay.textContent = text;
  previewDisplay.classList.toggle('is-long', lang !== 'custom' && length === 'long' || (lang === 'custom' && text.includes('\n')));
  document.body.classList.toggle('is-custom', lang === 'custom');
  document.body.classList.toggle('is-zh', lang === 'zh');
  const citeEl = document.querySelector('#workCite');
  citeEl.textContent = currentCite();
  if (activeFont) paintPreview(activeFont);
}

function pageSize() {
  const cols = getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length || 3;
  const row = view === 'list' ? 56 : 108;
  const extra = Math.ceil((grid.clientHeight || 480) / row) + 2;
  return Math.max(cols * 3, cols * extra);
}

