customText.oninput = () => {
  if (lang === 'custom') applyPreviewText();
};

document.querySelectorAll('.tab').forEach((button) => {
  button.onclick = () => {
    document.querySelector('.tab.active').classList.remove('active');
    button.classList.add('active');
    filter = button.dataset.filter;
    if (filter === 'hot') {
      sort = 'usage';
      sortBox.value = 'usage';
    }
    resetList();
  };
});

document.querySelector('#clearSelected').onclick = () => {
  previewGen += 1;
  activeFont = null;
  previewDisplay.classList.remove('is-live');
  previewDisplay.style.fontFamily = '';
  previewDisplay.style.fontWeight = '';
  previewDisplay.style.fontSynthesis = '';
  hideSelected();
  grid.querySelectorAll('.font-card').forEach((card) => card.classList.remove('is-current'));
};

async function downloadFontFile(font, button, idleLabel) {
  if (!font?.path || !button) return;
  const name = font.path.split('/').pop() || `${font.name}.ttf`;
  button.dataset.state = 'loading';
  button.disabled = true;
  try {
    let blob = null;
    const cached = await cacheGet(font);
    if (cached) blob = new Blob([cached]);
    if (!blob) {
      for (const url of fontUrls(font)) {
        try {
          const res = await fetch(url);
          if (!res.ok) continue;
          blob = await res.blob();
          const buf = await blob.arrayBuffer();
          cachePut(font, buf);
          blob = new Blob([buf]);
          break;
        } catch {}
      }
    }
    if (!blob) throw new Error('fetch');
    const href = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = href;
    link.download = name;
    link.click();
    URL.revokeObjectURL(href);
    button.dataset.state = 'success';
  } catch {
    button.dataset.state = 'error';
    window.open(fontUrls(font)[0], '_blank', 'noopener');
  } finally {
    button.disabled = false;
    button.textContent = idleLabel;
  }
}

document.querySelector('#downloadFont').onclick = () => {
  if (!activeFont?.path) return;
  const button = document.querySelector('#downloadFont');
  downloadFontFile(activeFont, button, `下载 ${activeFont.size}`);
};

sortBox.onchange = (event) => {
  sort = event.target.value;
  resetList();
};

search.oninput = resetList;

document.querySelectorAll('.view').forEach((button) => {
  button.onclick = () => {
    document.querySelector('.view.active').classList.remove('active');
    button.classList.add('active');
    view = button.dataset.view;
    resetList();
  };
});

document.querySelector('#themeToggle').onclick = () => {
  const light = document.body.classList.toggle('light');
  localStorage.setItem('ziku-theme', light ? 'light' : 'dark');
};

grid.addEventListener('scroll', () => {
  if (grid.scrollTop + grid.clientHeight < grid.scrollHeight - 160) return;
  const total = filtered().length;
  if (limit >= total) return;
  limit += pageSize();
  render();
});

function setTheater(on) {
  if (on && !activeFont) {
    const first = filtered()[0];
    if (first) selectFont(first);
  }
  document.body.classList.toggle('is-theater', on);
  const button = document.querySelector('#theaterToggle');
  button.textContent = on ? '退出全屏' : '全屏';
  button.setAttribute('aria-pressed', on ? 'true' : 'false');
  updateTheaterCaption(activeFont);
  if (!on && activeFont) {
    const index = filtered().indexOf(activeFont);
    if (index >= limit) {
      limit = index + 1;
      render();
    }
  }
}

document.querySelector('#theaterToggle').onclick = () => {
  setTheater(!document.body.classList.contains('is-theater'));
};

document.querySelector('#theaterPrev').onclick = () => stepFont(-1);
document.querySelector('#theaterNext').onclick = () => stepFont(1);

document.addEventListener('keydown', (event) => {
  const typing = event.target.closest('input, textarea');
  if (document.body.classList.contains('is-theater') && !typing) {
    if (event.key === 'Escape') {
      event.preventDefault();
      setTheater(false);
      return;
    }
    if (event.key === 'ArrowLeft' || event.key === 'ArrowUp' || event.key === 'h' || event.key === 'k') {
      event.preventDefault();
      stepFont(-1);
      return;
    }
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown' || event.key === 'l' || event.key === 'j') {
      event.preventDefault();
      stepFont(1);
      return;
    }
  }
  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
    event.preventDefault();
    search.focus();
  }
});

window.addEventListener('resize', () => {
  if (limit < pageSize()) resetList();
});

async function init() {
  try {
    fonts = (await (await fetch('data.json?v=ink22')).json()).map(normalize);
  } catch {
    fonts = [];
  }
  const total = document.querySelector('#catalogTotal');
  if (total) total.textContent = `${fonts.length.toLocaleString('zh-CN')} 款可商用`;
  renderPoets();
  applyPreviewText();
  limit = pageSize();
  render();
}

init();
